// Avatar — Adw.Avatar
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles avatar with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"

export interface AvatarProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** Gdk.Paintable, from Adw.Avatar */
  customImage?: ReactNode

  /** utf8, from Adw.Avatar */
  iconName?: string

  /** gboolean, from Adw.Avatar */
  showInitials?: boolean

  /** gint, from Adw.Avatar */
  size?: number

  /** utf8, from Adw.Avatar */
  text?: string
}

export function Avatar({ className, children, text }: AvatarProps) {
  return (
    <div className={cn("rounded-full", "font-bold", className)}>
      {text}
      {children}
    </div>
  )
}
